package org.schoolkernel.workspace;

import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.node.ArrayNode;
import tools.jackson.databind.node.ObjectNode;

/** A source revert is a selected-scope operation, never an undo or a source rebase. */
@Service
public class DefinitionRestorationService {
    private final WorkspaceStore repository;
    private final ObjectMapper json;
    private final DefinitionEntityService entities;
    private final DefinitionGridService grid;
    private final DefinitionRequirementService requirements;
    public DefinitionRestorationService(WorkspaceStore repository,ObjectMapper json,DefinitionEntityService entities,DefinitionGridService grid,DefinitionRequirementService requirements){this.repository=repository;this.json=json;this.entities=entities;this.grid=grid;this.requirements=requirements;}

    public ObjectNode inspect(String ifMatch){
        WorkspaceAggregate current=checked(ifMatch);ObjectNode draft=(ObjectNode)current.document().path("definitionDraft");JsonNode source=DefinitionRemovalService.sourceDefinition(draft);ObjectNode result=json.createObjectNode().put("version",current.version());ArrayNode choices=result.putArray("choices");
        if(!source.isObject()){result.put("explanation","No source definition exists. Discard authoring to return to the empty workspace.");return result;}
        addChoices(choices,"School",source.path("schoolId").asString(""),(ObjectNode)source,(ObjectNode)draft.path("definition"),true);
        for(var collection:new TreeMap<>(DefinitionRemovalService.COLLECTIONS).entrySet())for(JsonNode item:source.path(collection.getValue()))addChoices(choices,collection.getKey(),item.path("id").asString(""),(ObjectNode)item,find(draft.path("definition").path(collection.getValue()),item.path("id").asString("")),false);
        for(var entry:sourceGroups(draft).properties()){String id=entry.getKey();choices.addObject().put("type","Series").put("id",id).put("field","").put("label","Weekly requirement "+id+": source context (no member resurrection)");for(String field:DefinitionRequirementService.SHARED)choices.addObject().put("type","Series").put("id",id).put("field","defaults."+field).put("label","Weekly requirement "+id+": source default "+field+" (existing occurrence values retained)");}
        for(String id:List.of("soft.teacher-gap","soft.series-same-day","soft.undesirable-period","soft.non-preferred-room","soft.cohort-gap","soft.cohort-week-balance","soft.cohort-late-start")){int since=id.equals("soft.cohort-late-start")?3:id.startsWith("soft.cohort-")?2:1;if(draft.path("definition").path("catalogVersion").intValue()>=since)choices.addObject().put("type","Preference").put("id",id).put("field","weight").put("label","Preference "+id+": effective source weight");}
        result.put("explanation","Only source scopes are restorable. Newly added items have no source value; use Guided removal. Restoration does not resurrect dependencies or undo a removal operation.");return result;
    }
    private void addChoices(ArrayNode choices,String type,String id,ObjectNode source,ObjectNode saved,boolean school){
        if(!school)choices.addObject().put("type",type).put("id",id).put("field","").put("label",type+" "+id+": whole source item"+(saved==null?" (deleted)":""));
        if(saved==null)return;Set<String> fields=new TreeSet<>(source.propertyNames());fields.addAll(saved.propertyNames());
        // Optional attributes can be reverted to absence even when the source omitted them.
        fields.addAll(switch(type){case "Cohort"->List.of("homeRoomId","curatorTeacherId","availablePeriodIds","undesirablePeriodIds","maxDailyGaps","maxDailyLessonSpread","latestStartSlot","preferredLatestStartSlot","dailyLessonSpreadLimit");case "Lesson"->List.of("seriesId","periodLock","roomLock","preferredRoomIds","undesirablePeriodIds","requiredRoomCapabilityIds");case "School"->List.of("reservedPeriodIds","softConstraintOverrides");default->List.of();});
        for(String field:fields)if(!Set.of("id","schoolId","schemaVersion","catalogVersion","basedOnRevision").contains(field)&&(!school||Set.of("displayName","reservedPeriodIds","softConstraintOverrides").contains(field)))choices.addObject().put("type",type).put("id",id).put("field",field).put("label",type+" "+id+": "+field+" to source"+(source.has(field)?"":" (omitted)"));
    }
    public ObjectNode preview(String ifMatch,JsonNode request){WorkspaceAggregate current=checked(ifMatch);ObjectNode candidate=operation(current,request);ObjectNode result=json.createObjectNode().put("token",token(current,request)).put("version",current.version());result.set("selection",request.deepCopy());result.set("before",current.document().path("definitionDraft").path("definition"));result.set("after",candidate.path("definitionDraft").path("definition"));result.set("issues",candidate.path("definitionDraft").path("issues"));result.set("expiredPins",current.document().path("definitionDraft").path("expiredPins"));ArrayNode adjustments=result.putArray("effectiveSourceAdjustments");ObjectNode source=(ObjectNode)DefinitionRemovalService.sourceDefinition(current.document().path("definitionDraft")).deepCopy();DefinitionDraftService.upgrade(source,current.document().path("definitionDraft").path("definition").path("catalogVersion").intValue(),adjustments);result.put("explanation","Restore only this scope; retain enabled catalog, lineage and unrelated edits. Expired source attempt pins remain expired. Other deleted dependencies stay deleted; resulting blockers may be saved.");return result;}
    @Transactional public WorkspaceAggregate save(String ifMatch,JsonNode envelope){WorkspaceAggregate current=checked(ifMatch);if(!(envelope instanceof ObjectNode)||!envelope.propertyNames().equals(Set.of("request","token"))||!token(current,envelope.path("request")).equals(envelope.path("token").asString("")))throw problem("STALE_RESTORATION_PREVIEW","Review this exact restoration against the latest saved draft. No restoration was committed.");ObjectNode document=operation(current,envelope.path("request"));if(repository.replace(current.version(),WorkspaceState.DEFINITION_DRAFT,WorkspaceState.DEFINITION_DRAFT,document).isEmpty())throw new WorkspaceProblem(HttpStatus.PRECONDITION_FAILED,"STALE_WORKSPACE_VERSION","The draft changed. No restoration was committed.");return repository.load();}
    private ObjectNode operation(WorkspaceAggregate current,JsonNode request){
        if(!(request instanceof ObjectNode)||!request.propertyNames().equals(Set.of("type","id","field"))||!request.path("type").isTextual()||!request.path("id").isTextual()||!request.path("field").isTextual())throw problem("INVALID_RESTORATION_SCOPE","Select one source item or attribute.");
        String type=request.path("type").asString(""),id=request.path("id").asString(""),field=request.path("field").asString("");boolean available=false;for(JsonNode choice:inspect("\"ws-"+current.version()+"\"").path("choices"))if(choice.path("type").equals(request.path("type"))&&choice.path("id").equals(request.path("id"))&&choice.path("field").equals(request.path("field")))available=true;if(!available)throw problem("SOURCE_SCOPE_UNAVAILABLE","This scope has no restorable source value. Newly added items can be removed with Guided removal; an empty source can be restored by discarding authoring.");
        ObjectNode document=((ObjectNode)current.document()).deepCopy(),draft=(ObjectNode)document.path("definitionDraft"),definition=(ObjectNode)draft.path("definition"),source=(ObjectNode)DefinitionRemovalService.sourceDefinition(draft).deepCopy();DefinitionDraftService.upgrade(source,definition.path("catalogVersion").intValue(),json.createArrayNode());
        // Source pins keep their immutable provenance, but are not promoted into successor policy.
        for(JsonNode pin:draft.path("expiredPins")){ObjectNode lesson=find(source.path("lessons"),pin.path("lessonId").asString(""));if(lesson!=null)lesson.remove(pin.path("field").asString(""));}
        if(type.equals("Series")){ObjectNode context=requirements.context(draft),original=(ObjectNode)sourceGroups(draft).path(id),group=context.has(id)?(ObjectNode)context.path(id).deepCopy():original.deepCopy();if(field.isEmpty()){for(String selected:List.of("cohortId","subjectId","defaults","mixedFields"))if(original.has(selected))group.set(selected,original.path(selected).deepCopy());else group.remove(selected);}else{String shared=field.substring("defaults.".length());if(original.path("defaults").has(shared))group.withObject("defaults").set(shared,original.path("defaults").path(shared).deepCopy());else group.withObject("defaults").remove(shared);}
            int count=0;ObjectNode exceptions=group.putObject("exceptions");for(JsonNode lesson:definition.path("lessons"))if(id.equals(lesson.path("seriesId").asString(""))){count++;String lessonId=lesson.path("id").asString("");Set<String> explicit=new LinkedHashSet<>();for(JsonNode value:context.path(id).path("exceptions").path(lessonId))explicit.add(value.asString(""));for(JsonNode value:original.path("exceptions").path(lessonId))explicit.add(value.asString(""));for(String shared:DefinitionRequirementService.SHARED)if(!lesson.path(shared).equals(group.path("defaults").path(shared)))explicit.add(shared);if(!explicit.isEmpty()){ArrayNode fields=exceptions.putArray(lessonId);explicit.forEach(fields::add);}}
            group.put("count",count).put("nextSequence",Math.max(group.path("nextSequence").asInt(1),original.path("nextSequence").asInt(1)));draft.withObject("editingContext").withObject("requirements").set(id,group);if(field.isEmpty())unreserve(draft,type,id);return complete(draft,definition,document,request);}
        if(type.equals("Preference")){ArrayNode overrides=definition.withArray("softConstraintOverrides");for(int i=overrides.size()-1;i>=0;i--)if(id.equals(overrides.get(i).path("constraintId").asString("")))overrides.remove(i);for(JsonNode row:source.path("softConstraintOverrides"))if(id.equals(row.path("constraintId").asString("")))overrides.add(row.deepCopy());if(overrides.isEmpty()&&!source.has("softConstraintOverrides"))definition.remove("softConstraintOverrides");return complete(draft,definition,document,request);}
        ObjectNode sourceItem=type.equals("School")?source:find(source.path(DefinitionRemovalService.COLLECTIONS.get(type)),id),saved=type.equals("School")?definition:find(definition.path(DefinitionRemovalService.COLLECTIONS.get(type)),id);
        String oldSeries=saved==null?"":saved.path("seriesId").asString("");
        if(field.isEmpty()){ArrayNode rows=definition.withArray(DefinitionRemovalService.COLLECTIONS.get(type));if(saved==null)rows.add(sourceItem.deepCopy());else for(int i=0;i<rows.size();i++)if(rows.get(i)==saved){rows.set(i,sourceItem.deepCopy());break;}}
        else if(sourceItem.has(field))saved.set(field,sourceItem.path(field).deepCopy());else saved.remove(field);
        if(type.equals("Lesson")){
            ObjectNode restored=find(definition.path("lessons"),id);ObjectNode locks=draft.withObject("editingContext").withObject("authoredLocks").withObject(id);for(String lock:List.of("periodLock","roomLock"))if(field.isEmpty()||field.equals(lock))locks.remove(lock);
            ObjectNode context=requirements.context(draft);Set<String> affected=new LinkedHashSet<>(List.of(oldSeries,restored.path("seriesId").asString("")));affected.remove("");
            for(String series:affected){ObjectNode group=context.has(series)?(ObjectNode)context.path(series):null;if(group==null)continue;int count=0;for(JsonNode lesson:definition.path("lessons"))if(series.equals(lesson.path("seriesId").asString("")))count++;group.put("count",count);ObjectNode exceptions=group.withObject("exceptions");exceptions.remove(id);if(series.equals(restored.path("seriesId").asString(""))){Set<String> selected=new LinkedHashSet<>();if(!field.isEmpty() && oldSeries.equals(restored.path("seriesId").asString("")))for(JsonNode value:current.document().path("definitionDraft").path("editingContext").path("requirements").path(series).path("exceptions").path(id))if(!field.equals(value.asString("")))selected.add(value.asString(""));for(JsonNode value:draft.path("sourceDocument").path("authoringContext").path("requirements").path(series).path("exceptions").path(id))if(field.isEmpty()||field.equals(value.asString(""))||field.equals("seriesId"))selected.add(value.asString(""));for(String shared:DefinitionRequirementService.SHARED)if((field.isEmpty()||field.equals(shared)||field.equals("seriesId"))&&!restored.path(shared).equals(group.path("defaults").path(shared)))selected.add(shared);ArrayNode fields=json.createArrayNode();for(String shared:selected)fields.add(shared);if(!fields.isEmpty())exceptions.set(id,fields);}draft.withObject("editingContext").withObject("requirements").set(series,group);}
        }
        if(field.isEmpty())unreserve(draft,type,id);
        return complete(draft,definition,document,request);
    }
    private ObjectNode sourceGroups(ObjectNode draft){ObjectNode source=(ObjectNode)DefinitionRemovalService.sourceDefinition(draft).deepCopy();DefinitionDraftService.upgrade(source,draft.path("definition").path("catalogVersion").intValue(),json.createArrayNode());for(JsonNode pin:draft.path("expiredPins")){ObjectNode lesson=find(source.path("lessons"),pin.path("lessonId").asString(""));if(lesson!=null)lesson.remove(pin.path("field").asString(""));}ObjectNode fake=json.createObjectNode();fake.set("definition",source);fake.set("editingContext",draft.path("sourceDocument").path("authoringContext").isObject()?draft.path("sourceDocument").path("authoringContext").deepCopy():json.createObjectNode());ObjectNode groups=requirements.context(fake);for(JsonNode pin:draft.path("expiredPins")){ObjectNode lesson=find(source.path("lessons"),pin.path("lessonId").asString(""));if(lesson==null)continue;String series=lesson.path("seriesId").asString(""),field=pin.path("field").asString("");boolean surviving=false;for(JsonNode member:source.path("lessons"))if(series.equals(member.path("seriesId").asString(""))&&member.has(field))surviving=true;if(!surviving&&groups.path(series).path("defaults").isObject())((ObjectNode)groups.path(series).path("defaults")).remove(field);}return groups;}
    private static void unreserve(ObjectNode draft,String type,String id){ArrayNode reservations=draft.withArray("removedIdentities");for(int i=reservations.size()-1;i>=0;i--)if(type.equals(reservations.get(i).path("ownerType").asString(""))&&id.equals(reservations.get(i).path("id").asString("")))reservations.remove(i);}
    private ObjectNode complete(ObjectNode draft,ObjectNode definition,ObjectNode document,JsonNode request){entities.refreshAllEntityIssues(draft);grid.refreshIssues(draft);draft.put("draftRevision",DefinitionDraftService.revision(definition));draft.withArray("restorationOperations").add(request.deepCopy());return document;}
    private static ObjectNode find(JsonNode rows,String id){for(JsonNode row:rows)if(id.equals(row.path("id").asString("")))return(ObjectNode)row;return null;}
    private WorkspaceAggregate checked(String ifMatch){WorkspaceAggregate current=repository.load();ImportService.requireMatchingVersion(ifMatch,current);if(current.state()!=WorkspaceState.DEFINITION_DRAFT)throw problem("INVALID_WORKSPACE_TRANSITION","Source restoration requires an open definition draft.");return current;}
    private static String token(WorkspaceAggregate current,JsonNode request){ObjectNode value=((ObjectNode)current.document()).deepCopy();value.put("previewVersion",current.version());value.set("restorationScope",request);return DefinitionDraftService.revision(value);}
    private static WorkspaceProblem problem(String code,String message){return new WorkspaceProblem(HttpStatus.CONFLICT,code,message);}
}
